import type { Point } from "@/registry/plot/lib/paths";
export type ParameterValues = Record<string, number>;

export function dataExtent(
  data: readonly (readonly number[])[],
  invalid: (value: number) => boolean = (value) => !Number.isFinite(value),
): readonly [number, number] | null {
  let low = Infinity;
  let high = -Infinity;

  for (const column of data) {
    for (const value of column) {
      if (invalid(value)) continue;
      if (value < low) low = value;
      if (value > high) high = value;
    }
  }

  return Number.isFinite(low) && Number.isFinite(high) ? [low, high] : null;
}

export interface BinCounts {
  counts: number[];
  low: number;
  high: number;
  binWidth: number;
}

export function binCounts(
  values: readonly number[],
  bins: number,
  domain?: readonly [number, number],
): BinCounts {
  const finite = values.filter(Number.isFinite);
  const binTotal = Number.isFinite(bins) ? Math.floor(bins) : 0;
  if (finite.length === 0 || binTotal <= 0) {
    return { counts: [], low: 0, high: 0, binWidth: 0 };
  }

  const low = domain?.[0] ?? Math.min(...finite);
  const high = domain?.[1] ?? Math.max(...finite);
  const binWidth = (high - low || 1) / binTotal;
  const counts = Array.from({ length: binTotal }, () => 0);

  for (const value of finite) {
    let index = Math.floor((value - low) / binWidth);
    if (value === high) index = binTotal - 1;
    if (index >= 0 && index < binTotal) counts[index]++;
  }

  return { counts, low, high, binWidth };
}

export function sampleFunction(
  fn: (x: number, parameters: Readonly<ParameterValues>) => number,
  domain: readonly [number, number],
  parameters: Readonly<ParameterValues> = {},
  samples = 400,
): Point[] {
  const count = Number.isFinite(samples)
    ? Math.max(2, Math.floor(samples))
    : 400;
  const [start, end] = domain;

  return Array.from({ length: count }, (_, index) => {
    const x = start + (index / (count - 1)) * (end - start);
    try {
      const y = fn(x, parameters);
      return [x, Number.isFinite(y) ? y : Number.NaN] as const;
    } catch {
      return [x, Number.NaN] as const;
    }
  });
}

import type { ContinuousScale } from "@/registry/plot/lib/scales";

export type Point = readonly [x: number, y: number];
export type LineInterpolation =
  | "linear"
  | "step-before"
  | "step-after"
  | "monotone";

/** Build separate paths for finite runs; invalid data never joins across a gap. */
export function linePath(
  data: readonly Point[],
  xScale: ContinuousScale,
  yScale: ContinuousScale,
  defined: (point: Point, index: number) => boolean = ([x, y]) =>
    Number.isFinite(x) && Number.isFinite(y),
  interpolation: LineInterpolation = "linear",
) {
  const segments: Point[][] = [];
  let segment: Point[] = [];
  data.forEach((point, index) => {
    const mapped: Point = [xScale(point[0]), yScale(point[1])];
    if (!defined(point, index) || !mapped.every(Number.isFinite)) {
      if (segment.length) segments.push(segment);
      segment = [];
    } else segment.push(mapped);
  });
  if (segment.length) segments.push(segment);
  return segments.map((points) => segmentPath(points, interpolation)).join(" ");
}

function segmentPath(points: Point[], interpolation: LineInterpolation) {
  const first = points[0]!;
  let path = `M ${first[0]} ${first[1]}`;
  const slopes = points
    .slice(1)
    .map(
      (point, index) =>
        (point[1] - points[index]![1]) / (point[0] - points[index]![0]),
    );
  const direction = Math.sign((points[1]?.[0] ?? first[0]) - first[0]);
  const monotone =
    interpolation === "monotone" &&
    slopes.every(Number.isFinite) &&
    points
      .slice(1)
      .every(
        (point, index) => Math.sign(point[0] - points[index]![0]) === direction,
      );
  // Harmonic-mean tangents preserve local extrema without introducing overshoot.
  const tangents = points.map((_, index) => {
    if (index === 0) return slopes[0] ?? 0;
    if (index === points.length - 1) return slopes[index - 1]!;
    const left = slopes[index - 1]!;
    const right = slopes[index]!;
    return left * right <= 0 ? 0 : 2 / (1 / left + 1 / right);
  });
  for (let index = 1; index < points.length; index++) {
    const [x, y] = points[index]!;
    const [px, py] = points[index - 1]!;
    if (interpolation === "step-before") path += ` L ${px} ${y} L ${x} ${y}`;
    else if (interpolation === "step-after")
      path += ` L ${x} ${py} L ${x} ${y}`;
    else if (monotone) {
      const third = (x - px) / 3;
      path += ` C ${px + third} ${py + third * tangents[index - 1]!} ${x - third} ${y - third * tangents[index]!} ${x} ${y}`;
    } else path += ` L ${x} ${y}`;
  }
  return path;
}

interface ContinuousScaleBase {
  (value: number): number;
  invert(value: number): number;
  domain: readonly [number, number];
  range: readonly [number, number];
}

export interface LinearScale extends ContinuousScaleBase {
  type: "linear";
}

export interface LogScale extends ContinuousScaleBase {
  type: "log";
  base: number;
}

export type ContinuousScale = LinearScale | LogScale;

export interface OrdinalScale<T extends string | number = string | number> {
  (value: T): number;
  domain: readonly T[];
  range: readonly [number, number];
  bandwidth: number;
  type: "ordinal";
}

export type Scale = ContinuousScale | OrdinalScale;

function makeLinear(
  domain: readonly [number, number],
  range: readonly [number, number],
): LinearScale {
  const [d0, d1] = domain;
  const [r0, r1] = range;
  const domainSpan = d1 - d0;

  const fn = (value: number) =>
    domainSpan === 0
      ? (r0 + r1) / 2
      : ((value - d0) / domainSpan) * (r1 - r0) + r0;

  const result = fn as LinearScale;
  result.invert = (value) =>
    r1 === r0 ? d0 : ((value - r0) / (r1 - r0)) * domainSpan + d0;
  result.domain = domain;
  result.range = range;
  result.type = "linear";
  return result;
}

function makeLog(
  domain: readonly [number, number],
  range: readonly [number, number],
  base: number,
): LogScale {
  const [d0, d1] = domain;
  if (d0 <= 0 || d1 <= 0) {
    throw new Error(`scale.log: domain values must be > 0, got [${d0}, ${d1}]`);
  }
  if (base <= 1) {
    throw new Error(`scale.log: base must be > 1, got ${base}`);
  }

  const logBase = Math.log(base);
  const logD0 = Math.log(d0) / logBase;
  const logD1 = Math.log(d1) / logBase;
  const [r0, r1] = range;

  const fn = (value: number) => {
    const logValue = Math.log(value) / logBase;
    return logD1 === logD0
      ? (r0 + r1) / 2
      : ((logValue - logD0) / (logD1 - logD0)) * (r1 - r0) + r0;
  };

  const result = fn as LogScale;
  result.invert = (value) => {
    const logValue =
      r1 === r0 ? logD0 : ((value - r0) / (r1 - r0)) * (logD1 - logD0) + logD0;
    return Math.pow(base, logValue);
  };
  result.domain = domain;
  result.range = range;
  result.type = "log";
  result.base = base;
  return result;
}

function makeOrdinal<T extends string | number>(
  domain: readonly T[],
  range: readonly [number, number],
): OrdinalScale<T> {
  const [r0, r1] = range;
  const bandwidth = domain.length === 0 ? 0 : (r1 - r0) / domain.length;

  const fn = (value: T) => {
    const index = domain.indexOf(value);
    if (index === -1) {
      throw new Error(
        `scale.ordinal: value ${String(value)} not in domain [${domain.join(", ")}]`,
      );
    }
    return r0 + index * bandwidth + bandwidth / 2;
  };

  const result = fn as OrdinalScale<T>;
  result.domain = domain;
  result.range = range;
  result.bandwidth = bandwidth;
  result.type = "ordinal";
  return result;
}

export const scale = {
  linear({
    domain,
    range,
  }: {
    domain: readonly [number, number];
    range: readonly [number, number];
  }): LinearScale {
    return makeLinear(domain, range);
  },

  log({
    domain,
    range,
    base = 10,
  }: {
    domain: readonly [number, number];
    range: readonly [number, number];
    base?: number;
  }): LogScale {
    return makeLog(domain, range, base);
  },

  ordinal<T extends string | number>({
    domain,
    range,
  }: {
    domain: readonly T[];
    range: readonly [number, number];
  }): OrdinalScale<T> {
    return makeOrdinal(domain, range);
  },
};

import type {
  Scale,
  OrdinalScale,
  LinearScale,
  LogScale,
} from "@/registry/plot/lib/scales";

/** Compute readable tick values for a linear, logarithmic, or ordinal scale. */
export function ticks<T extends string | number>(
  currentScale: Scale | OrdinalScale<T>,
  count = 5,
): Array<number | string> {
  if (currentScale.type === "ordinal") {
    return [...currentScale.domain] as Array<number | string>;
  }

  if (currentScale.type === "log") {
    return logTicks(currentScale);
  }

  return linearTicks(currentScale, count);
}

function linearTicks(currentScale: LinearScale, count: number): number[] {
  const [first, last] = currentScale.domain;
  const descending = last < first;
  const low = Math.min(first, last);
  const high = Math.max(first, last);
  const span = high - low;
  if (span === 0) return [first];

  const roughStep = span / Math.max(count, 2);
  const magnitude = Math.floor(Math.log10(roughStep));
  const power = Math.pow(10, magnitude);
  const ratio = roughStep / power;
  const multiplier = ratio <= 1 ? 1 : ratio <= 2 ? 2 : ratio <= 5 ? 5 : 10;
  const step = multiplier * power;
  const start = Math.ceil(low / step) * step;
  const end = Math.floor(high / step) * step;
  const result: number[] = [];
  const steps = Math.round((end - start) / step);

  for (let index = 0; index <= steps; index++) {
    result.push(Number.parseFloat((start + index * step).toPrecision(12)));
  }

  const values = result.length >= 2 ? result : [low, high];
  return descending ? values.reverse() : values;
}

function logTicks(currentScale: LogScale): number[] {
  const [first, last] = currentScale.domain;
  const descending = last < first;
  const low = Math.min(first, last);
  const high = Math.max(first, last);
  const logBase = Math.log(currentScale.base);
  const start = Math.ceil(Math.log(low) / logBase);
  const end = Math.floor(Math.log(high) / logBase);
  const result: number[] = [];

  for (let exponent = start; exponent <= end; exponent++) {
    result.push(Math.pow(currentScale.base, exponent));
  }

  const values = result.length >= 2 ? result : [low, high];
  return descending ? values.reverse() : values;
}

"use client";

import * as React from "react";
import { usePlot } from "@/registry/plot/ui/plot-context";
import type { Scale } from "@/registry/plot/lib/scales";
import { ticks } from "@/registry/plot/lib/ticks";
export interface AxisProps {
  scale: Scale;
  side: "bottom" | "left" | "top" | "right";
  label?: string;
  tickFormat?: (value: number | string) => React.ReactNode;
  numTicks?: number;
  tickSize?: number;
  className?: string;
}

export function Axis({
  scale: currentScale,
  side,
  label,
  tickFormat = String,
  numTicks = 5,
  tickSize = 6,
  className,
}: AxisProps) {
  const horizontal = side === "bottom" || side === "top";
  const values = ticks(currentScale, numTicks);
  const [rangeStart, rangeEnd] = currentScale.range;
  const tickDirection = side === "bottom" || side === "right" ? 1 : -1;

  const position = (value: number | string) => {
    if (currentScale.type === "ordinal") {
      return currentScale(value as string);
    }
    return currentScale(value as number);
  };

  if (horizontal) {
    const labelOffset = tickDirection * (tickSize + 14);
    const axisLabelOffset = tickDirection * (tickSize + 32);

    return (
      <g className={className}>
        <line
          x1={rangeStart}
          y1={0}
          x2={rangeEnd}
          y2={0}
          stroke="var(--border)"
        />
        {values.map((value) => {
          const x = position(value);
          return (
            <g key={String(value)} transform={`translate(${x}, 0)`}>
              <line
                x1={0}
                y1={0}
                x2={0}
                y2={tickDirection * tickSize}
                stroke="var(--border)"
              />
              <text
                x={0}
                y={labelOffset}
                textAnchor="middle"
                dominantBaseline={side === "bottom" ? "hanging" : "auto"}
                fill="var(--muted-foreground)"
                fontFamily="var(--font-mono), ui-monospace, monospace"
                fontSize={11}
              >
                {tickFormat(value)}
              </text>
            </g>
          );
        })}
        {label ? (
          <text
            x={(rangeStart + rangeEnd) / 2}
            y={axisLabelOffset}
            textAnchor="middle"
            dominantBaseline={side === "bottom" ? "hanging" : "auto"}
            fill="var(--foreground)"
            fontFamily="var(--font-sans), ui-sans-serif, sans-serif"
            fontSize={12}
            fontWeight={500}
          >
            {label}
          </text>
        ) : null}
      </g>
    );
  }

  const labelOffset = tickDirection * (tickSize + 6);
  const axisLabelOffset = tickDirection * (tickSize + 38);
  const center = (rangeStart + rangeEnd) / 2;

  return (
    <g className={className}>
      <line
        x1={0}
        y1={rangeStart}
        x2={0}
        y2={rangeEnd}
        stroke="var(--border)"
      />
      {values.map((value) => {
        const y = position(value);
        return (
          <g key={String(value)} transform={`translate(0, ${y})`}>
            <line
              x1={0}
              y1={0}
              x2={tickDirection * tickSize}
              y2={0}
              stroke="var(--border)"
            />
            <text
              x={labelOffset}
              y={0}
              textAnchor={side === "left" ? "end" : "start"}
              dominantBaseline="middle"
              fill="var(--muted-foreground)"
              fontFamily="var(--font-mono), ui-monospace, monospace"
              fontSize={11}
            >
              {tickFormat(value)}
            </text>
          </g>
        );
      })}
      {label ? (
        <text
          x={axisLabelOffset}
          y={center}
          textAnchor="middle"
          transform={`rotate(-90, ${axisLabelOffset}, ${center})`}
          fill="var(--foreground)"
          fontFamily="var(--font-sans), ui-sans-serif, sans-serif"
          fontSize={12}
          fontWeight={500}
        >
          {label}
        </text>
      ) : null}
    </g>
  );
}

// The low-level Axis export above also supports legacy frames and ordinal scales.
export interface PlotAxisProps extends Omit<AxisProps, "scale" | "side"> {
  side?: "bottom" | "top";
}

export function PlotXAxis({ side = "bottom", ...props }: PlotAxisProps) {
  const { xScale, innerHeight } = usePlot();
  return (
    <g transform={`translate(0, ${side === "bottom" ? innerHeight : 0})`}>
      <Axis {...props} scale={xScale} side={side} />
    </g>
  );
}

export function PlotYAxis({
  side = "left",
  ...props
}: Omit<PlotAxisProps, "side"> & { side?: "left" | "right" }) {
  const { yScale, innerWidth } = usePlot();
  return (
    <g transform={`translate(${side === "right" ? innerWidth : 0}, 0)`}>
      <Axis {...props} scale={yScale} side={side} />
    </g>
  );
}

export function PlotGrid({
  x = true,
  y = true,
  xNumTicks = 5,
  yNumTicks = 5,
  ...props
}: Omit<React.ComponentProps<"g">, "x" | "y"> & {
  x?: boolean;
  y?: boolean;
  xNumTicks?: number;
  yNumTicks?: number;
}) {
  const { xScale, yScale, innerWidth, innerHeight } = usePlot();
  return (
    <g stroke="var(--border)" strokeOpacity={0.5} aria-hidden="true" {...props}>
      {x &&
        ticks(xScale, xNumTicks).map((value) => (
          <line
            key={`x-${value}`}
            x1={xScale(Number(value))}
            x2={xScale(Number(value))}
            y1={0}
            y2={innerHeight}
          />
        ))}
      {y &&
        ticks(yScale, yNumTicks).map((value) => (
          <line
            key={`y-${value}`}
            y1={yScale(Number(value))}
            y2={yScale(Number(value))}
            x1={0}
            x2={innerWidth}
          />
        ))}
    </g>
  );
}

"use client";

import * as React from "react";
import type { ContinuousScale } from "@/registry/plot/lib/scales";

export type PlotMarkerType = "none" | "circle" | "square" | "diamond";
export interface PlotSeriesMetadata {
  id: string;
  label: string;
  color: string;
  kind: "line" | "scatter" | "histogram" | "heatmap";
  marker?: PlotMarkerType;
  strokeWidth?: string | number;
  strokeDasharray?: string | number;
  strokeLinecap?: "butt" | "round" | "square" | "inherit";
}

export interface PlotRootContextValue {
  xDomain: readonly [number, number];
  yDomain: readonly [number, number];
  xScaleType: "linear" | "log";
  yScaleType: "linear" | "log";
  xLogBase: number;
  yLogBase: number;
  titleId: string;
  descriptionId: string;
  titlePresent: boolean;
  descriptionPresent: boolean;
  setTitlePresent: (present: boolean) => void;
  setDescriptionPresent: (present: boolean) => void;
  series: readonly PlotSeriesMetadata[];
  registerSeries: (series: PlotSeriesMetadata) => void;
  unregisterSeries: (id: string) => void;
}

export const PlotRootContext = React.createContext<PlotRootContextValue | null>(
  null,
);
export const PlotCanvasContext = React.createContext<{
  xScale: ContinuousScale;
  yScale: ContinuousScale;
  innerWidth: number;
  innerHeight: number;
} | null>(null);

export function usePlotRoot() {
  const context = React.useContext(PlotRootContext);
  if (!context) throw new Error("Plot components must be inside <Plot>.");
  return context;
}

export function usePlot() {
  const context = React.useContext(PlotCanvasContext);
  if (!context)
    throw new Error("Plot data and axes must be inside <PlotCanvas>.");
  return context;
}

export function usePlotSeries(metadata: PlotSeriesMetadata) {
  const { registerSeries, unregisterSeries } = usePlotRoot();
  const {
    id,
    label,
    color,
    kind,
    marker,
    strokeWidth,
    strokeDasharray,
    strokeLinecap,
  } = metadata;
  React.useEffect(() => {
    registerSeries({
      id,
      label,
      color,
      kind,
      marker,
      strokeWidth,
      strokeDasharray,
      strokeLinecap,
    });
  }, [
    registerSeries,
    id,
    label,
    color,
    kind,
    marker,
    strokeWidth,
    strokeDasharray,
    strokeLinecap,
  ]);
  React.useEffect(() => () => unregisterSeries(id), [unregisterSeries, id]);
}

export function PlotMarker({
  marker = "circle",
  x,
  y,
  size = 3,
  ...props
}: Omit<React.SVGProps<SVGElement>, "ref"> & {
  marker?: PlotMarkerType;
  x: number;
  y: number;
  size?: number;
}) {
  if (marker === "none") return null;
  if (marker === "square")
    return (
      <rect
        {...props}
        x={x - size}
        y={y - size}
        width={size * 2}
        height={size * 2}
      />
    );
  if (marker === "diamond")
    return (
      <path
        {...props}
        d={`M ${x} ${y - size} L ${x + size} ${y} L ${x} ${y + size} L ${x - size} ${y} Z`}
      />
    );
  return <circle {...props} cx={x} cy={y} r={size} />;
}

"use client";

import * as React from "react";

export function PlotControls({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      {...props}
      className={`grid gap-4 rounded-lg border p-4 ${className ?? ""}`.trim()}
    />
  );
}

export interface PlotSliderProps
  extends Omit<
    React.ComponentProps<"input">,
    | "type"
    | "value"
    | "defaultValue"
    | "onChange"
    | "onInput"
    | "min"
    | "max"
    | "step"
  > {
  label: string;
  value: number;
  onValueChange: (value: number) => void;
  min: number;
  max: number;
  step?: number;
  formatValue?: (value: number) => string;
}

export function PlotSlider({
  label,
  value,
  onValueChange,
  min,
  max,
  step,
  formatValue = String,
  id,
  className,
  ...props
}: PlotSliderProps) {
  const generatedId = React.useId();
  const inputId = id ?? generatedId;
  return (
    <div className="grid gap-2">
      <div className="flex items-baseline justify-between gap-4">
        <label htmlFor={inputId} className="text-sm">
          {label}
        </label>
        <output
          htmlFor={inputId}
          className="font-mono text-sm tabular-nums text-muted-foreground"
        >
          {formatValue(value)}
        </output>
      </div>
      <input
        {...props}
        id={inputId}
        type="range"
        min={min}
        max={max}
        step={step ?? (Math.abs(max - min) / 100 || 1)}
        value={value}
        onInput={(event) => onValueChange(event.currentTarget.valueAsNumber)}
        className={`h-2 w-full cursor-pointer accent-primary ${className ?? ""}`.trim()}
      />
    </div>
  );
}

"use client";

import * as React from "react";
import {
  scale,
  type Scale,
  type ContinuousScale,
} from "@/registry/plot/lib/scales";
import { Axis } from "@/registry/plot/ui/plot-axis";
export interface PlotMargin {
  top?: number;
  right?: number;
  bottom?: number;
  left?: number;
}

export interface PlotRenderArgs<
  XScale extends Scale = Scale,
  YScale extends Scale = Scale,
> {
  xScale: XScale;
  yScale: YScale;
  innerWidth: number;
  innerHeight: number;
}

export interface FrameProps<
  XScale extends Scale = Scale,
  YScale extends Scale = Scale,
> {
  width: number;
  height: number;
  margin?: PlotMargin;
  xScale: XScale;
  yScale: YScale;
  xLabel?: string;
  yLabel?: string;
  xTickFormat?: (value: number | string) => React.ReactNode;
  yTickFormat?: (value: number | string) => React.ReactNode;
  xNumTicks?: number;
  yNumTicks?: number;
  title?: string;
  className?: string;
  style?: React.CSSProperties;
  children?:
    | React.ReactNode
    | ((args: PlotRenderArgs<XScale, YScale>) => React.ReactNode);
}

function resolveMargin(
  margin: PlotMargin | undefined,
  xLabel: string | undefined,
  yLabel: string | undefined,
) {
  return {
    top: margin?.top ?? 16,
    right: margin?.right ?? 16,
    bottom: margin?.bottom ?? (xLabel ? 58 : 38),
    left: margin?.left ?? (yLabel ? 64 : 46),
  };
}

export function Frame<XScale extends Scale, YScale extends Scale>({
  width,
  height,
  margin: marginInput,
  xScale,
  yScale,
  xLabel,
  yLabel,
  xTickFormat,
  yTickFormat,
  xNumTicks,
  yNumTicks,
  title,
  className,
  style,
  children,
}: FrameProps<XScale, YScale>) {
  const margin = resolveMargin(marginInput, xLabel, yLabel);
  const innerWidth = Math.max(0, width - margin.left - margin.right);
  const innerHeight = Math.max(0, height - margin.top - margin.bottom);
  const renderArgs = { xScale, yScale, innerWidth, innerHeight };
  const content =
    typeof children === "function" ? children(renderArgs) : children;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width={width}
      height={height}
      role="img"
      aria-label={title ?? "Plot"}
      className={className}
      style={{ display: "block", width: "100%", height: "auto", ...style }}
    >
      {title ? <title>{title}</title> : null}
      <g transform={`translate(${margin.left}, ${margin.top})`}>
        {content}
        <g transform={`translate(0, ${innerHeight})`}>
          <Axis
            scale={xScale}
            side="bottom"
            label={xLabel}
            tickFormat={xTickFormat}
            numTicks={xNumTicks}
          />
        </g>
        <Axis
          scale={yScale}
          side="left"
          label={yLabel}
          tickFormat={yTickFormat}
          numTicks={yNumTicks}
        />
      </g>
    </svg>
  );
}

export interface LegacyPlotProps
  extends Omit<
    FrameProps<ContinuousScale, ContinuousScale>,
    "xScale" | "yScale" | "children"
  > {
  xDomain: readonly [number, number];
  yDomain: readonly [number, number];
  xScaleType?: "linear" | "log";
  yScaleType?: "linear" | "log";
  xLogBase?: number;
  yLogBase?: number;
  children?:
    | React.ReactNode
    | ((
        args: PlotRenderArgs<ContinuousScale, ContinuousScale>,
      ) => React.ReactNode);
}

/** A convenient frame that derives correctly sized x and y scales from domains. */
export function LegacyPlot({
  xDomain,
  yDomain,
  xScaleType = "linear",
  yScaleType = "linear",
  xLogBase = 10,
  yLogBase = 10,
  margin: marginInput,
  xLabel,
  yLabel,
  width,
  height,
  children,
  ...props
}: LegacyPlotProps) {
  const margin = resolveMargin(marginInput, xLabel, yLabel);
  const innerWidth = Math.max(0, width - margin.left - margin.right);
  const innerHeight = Math.max(0, height - margin.top - margin.bottom);
  const xScale =
    xScaleType === "log"
      ? scale.log({ domain: xDomain, range: [0, innerWidth], base: xLogBase })
      : scale.linear({ domain: xDomain, range: [0, innerWidth] });
  const yScale =
    yScaleType === "log"
      ? scale.log({ domain: yDomain, range: [innerHeight, 0], base: yLogBase })
      : scale.linear({ domain: yDomain, range: [innerHeight, 0] });

  return (
    <Frame
      {...props}
      width={width}
      height={height}
      margin={margin}
      xScale={xScale}
      yScale={yScale}
      xLabel={xLabel}
      yLabel={yLabel}
    >
      {children}
    </Frame>
  );
}

