export function PlotFunction({
  fn,
  parameters = {},
  samples = 400,
  ...props
}: PlotFunctionProps) {
  const { xScale } = usePlot();
  return (
    <PlotLine
      {...props}
      data={sampleFunction(fn, xScale.domain, parameters, samples)}
    />
  );
}

